//! What code generated by `src/codegen/bindgen.ts` hands to a binding's Rust body: `docs/project/bindgen.mdx`.

use core::cell::UnsafeCell;
use core::ffi::c_void;
use core::marker::{PhantomData, PhantomPinned};
use core::ptr::NonNull;

use crate::{
    ArrayBuffer, ErrorCode, JSGlobalObject, JSObject, JSString, JSValue, JsError, JsThread,
    PinnedArrayBuffer, Strong, ThreadIsolated, ThreadIsolatedArg,
};

#[path = "bindgen/extern_types.rs"]
pub mod extern_types;

/// Makes `'a` invariant, so two calls' lifetimes never unify.
type InvariantLifetime<'a> = PhantomData<fn(&'a ()) -> &'a ()>;
type NotSend = PhantomData<*mut ()>;
/// As `bun_opaque::opaque_ffi!`: a reference to it is a bare pointer to LLVM (no `noalias`).
type OpaqueFfi = (UnsafeCell<[u8; 0]>, PhantomPinned);

// ───────────────────────────── capabilities ─────────────────────────────

/// What allocates, reads JS-owned memory and describes an error to throw. It cannot run JavaScript.
#[repr(C)]
pub struct JsHeap<'a>(OpaqueFfi, InvariantLifetime<'a>, NotSend);

/// What reaches the Rust payloads of wrapper objects.
#[repr(C)]
pub struct JsPayloads<'a>(OpaqueFfi, InvariantLifetime<'a>, NotSend);

/// `&mut JsScope` is what runs JavaScript. It is the `JSGlobalObject*`: both fields are zero-sized at offset 0.
#[repr(C)]
pub struct JsScope<'a> {
    pub heap: JsHeap<'a>,
    pub payloads: JsPayloads<'a>,
}

impl<'a> JsHeap<'a> {
    /// For this module, which passes it to nothing that runs JavaScript except on behalf of a [`JsScope`].
    #[inline(always)]
    fn global_object(&self) -> &JSGlobalObject {
        // SAFETY: a `JsHeap` only exists at the address of a live global (see `JsScope::with`).
        unsafe { JSGlobalObject::opaque_ref_nn(core::ptr::from_ref(self).cast()) }
    }

    /// For what takes the global object only to allocate or to throw.
    ///
    /// # Safety
    /// Nothing it is passed to runs JavaScript. Throwing tells the debugger, which can, so after a throw the body
    /// returns without reading what it borrowed.
    #[inline(always)]
    pub unsafe fn global(&self) -> &JSGlobalObject {
        self.global_object()
    }

    #[inline(always)]
    fn global_ptr(&self) -> *mut JSGlobalObject {
        self.global_object().as_mut_ptr()
    }

    #[inline]
    pub fn create_utf8_string(&self, utf8: &[u8]) -> Result<'a, JsLocal<'a, JSString>> {
        JsLocal::from_js_result(crate::bun_string_jsc::create_utf8_for_js(
            self.global_object(),
            utf8,
        ))
    }

    /// A string with a copy of `characters`, at most [`JSString::MAX_LENGTH`] of them.
    #[inline(always)]
    pub fn create_latin1_string(&self, characters: &[u8]) -> JsLocal<'a, JSString> {
        JsLocal::from_raw(JSString::create_latin1(self.global_object(), characters))
    }

    /// A string of `length` 8-bit characters, 2 to [`JSString::MAX_LENGTH`].
    ///
    /// # Safety
    /// `fill` writes all of them.
    #[inline(always)]
    pub unsafe fn create_latin1_string_with(
        &self,
        length: usize,
        fill: impl FnOnce(*mut u8),
    ) -> JsLocal<'a, JSString> {
        // SAFETY: forwarded. Without the `JsHeap`, `fill` allocates nothing in the heap.
        JsLocal::from_raw(unsafe {
            JSString::create_latin1_with(self.global_object(), length, fill)
        })
    }

    /// A `Uint8Array` whose bytes are whatever the allocator left there.
    #[inline]
    pub fn create_uninitialized_uint8_array(
        &self,
        length: usize,
    ) -> Result<'a, JsLocal<'a, BufferSource>> {
        JsLocal::from_js_result(JSValue::create_uninitialized_uint8_array(
            self.global_object(),
            length,
        ))
    }

    /// A `Uint8Array` with a copy of `bytes`.
    #[inline]
    pub fn create_uint8_array(&self, bytes: &[u8]) -> Result<'a, JsLocal<'a, BufferSource>> {
        JsLocal::from_js_result(ArrayBuffer::create_uint8_array(self.global_object(), bytes))
    }

    /// A `Buffer` with a copy of `bytes`.
    #[inline]
    pub fn create_buffer(&self, bytes: &[u8]) -> Result<'a, JsLocal<'a, BufferSource>> {
        JsLocal::from_js_result(ArrayBuffer::create_buffer(self.global_object(), bytes))
    }

    /// A `Uint8Array` that takes over the allocation of `bytes`.
    #[inline]
    pub fn create_uint8_array_from_box(
        &self,
        bytes: Box<[u8]>,
    ) -> Result<'a, JsLocal<'a, BufferSource>> {
        JsLocal::from_js_result(crate::JSUint8Array::from_bytes(self.global_object(), bytes))
    }

    /// A `Buffer` that takes over the allocation of `bytes`.
    #[inline]
    pub fn create_buffer_from_box(
        &self,
        bytes: Box<[u8]>,
    ) -> Result<'a, JsLocal<'a, BufferSource>> {
        JsLocal::from_js_result(JSValue::create_buffer_from_box(self.global_object(), bytes))
    }

    /// An `Error` for the body to return. It is thrown after that.
    #[cold]
    pub fn error(&self, args: core::fmt::Arguments<'_>) -> Error<'a> {
        Error::unthrown(self.global_object().create_error_instance(args))
    }

    /// As [`error`](Self::error), a `TypeError`.
    #[cold]
    pub fn type_error(&self, args: core::fmt::Arguments<'_>) -> Error<'a> {
        Error::unthrown(self.global_object().create_type_error_instance(args))
    }

    /// As [`error`](Self::error), a `RangeError`.
    #[cold]
    pub fn range_error(&self, args: core::fmt::Arguments<'_>) -> Error<'a> {
        Error::unthrown(self.global_object().create_range_error_instance(args))
    }

    /// As [`error`](Self::error), with a `code`, which also picks the class.
    #[cold]
    pub fn error_with_code(&self, code: ErrorCode, args: core::fmt::Arguments<'_>) -> Error<'a> {
        Error::unthrown(code.fmt(self.global_object(), args))
    }

    /// What [`JSGlobalObject::throw_invalid_arguments`] throws.
    #[cold]
    pub fn invalid_arguments(&self, args: core::fmt::Arguments<'_>) -> Error<'a> {
        self.error_with_code(ErrorCode::INVALID_ARG_TYPE, args)
    }
}

impl<'a> JsScope<'a> {
    /// # Safety
    /// `global` is this thread's live global object, JavaScript may run here (the engine or the event loop entered the
    /// caller, and not to finalize or visit a cell), and nothing borrowed through another `JsScope` is still in use.
    #[inline(always)]
    pub unsafe fn with<R>(
        global: *mut JSGlobalObject,
        f: impl for<'call> FnOnce(&mut JsScope<'call>) -> R,
    ) -> R {
        // SAFETY: `JsScope` is zero-sized and `global` is non-null.
        f(unsafe { &mut *global.cast::<JsScope<'_>>() })
    }

    /// Anything can be done with a `&JSGlobalObject`, so it borrows the whole `JsScope`.
    #[inline(always)]
    pub fn global(&mut self) -> &JSGlobalObject {
        self.heap.global_object()
    }

    /// For the APIs that take the tree's own proof of being on the JS thread.
    #[inline]
    pub fn js_thread(&mut self) -> JsThread<'_> {
        self.heap.global_object().js_thread_of_caller_no_frame()
    }
}

// ───────────────────────────── errors ─────────────────────────────

#[derive(Debug)]
enum ErrorState {
    Pending(JsError),
    /// Thrown once the body has returned: `VM::throwException` notifies the debugger, which can run code.
    ToThrow(JSValue),
}

/// The call failed with a JS exception.
#[derive(Debug)]
#[must_use = "dropping this leaves an exception pending (or never throws it)"]
pub struct Error<'a>(ErrorState, InvariantLifetime<'a>, NotSend);
pub type Result<'a, T> = core::result::Result<T, Error<'a>>;

impl<'a> Error<'a> {
    #[inline(always)]
    fn unthrown(value: JSValue) -> Self {
        Error(ErrorState::ToThrow(value), PhantomData, PhantomData)
    }

    /// `throw value`, once the body has returned.
    #[cold]
    pub fn from_value<T>(value: JsLocal<'a, T>) -> Self {
        Self::unthrown(value.0)
    }

    #[inline(always)]
    fn pending(error: JsError) -> Self {
        Error(ErrorState::Pending(error), PhantomData, PhantomData)
    }

    #[doc(hidden)]
    #[cold]
    #[inline(never)]
    pub fn into_host_fn_return(self, cx: &mut JsScope<'a>) -> JSValue {
        let global = cx.global();
        match self.0 {
            ErrorState::Pending(error) => crate::host_fn::host_call_error_value(global, error),
            ErrorState::ToThrow(value) => {
                let _ = global.throw_value(value);
                JSValue::ZERO
            }
        }
    }

    /// Throws it now, for a caller that is not a generated thunk.
    #[cold]
    pub fn into_js_error(self, global: &JSGlobalObject) -> JsError {
        match self.0 {
            ErrorState::Pending(error) => error,
            ErrorState::ToThrow(value) => global.throw_value(value),
        }
    }
}

impl From<JsError> for Error<'_> {
    #[inline(always)]
    fn from(error: JsError) -> Self {
        Error::pending(error)
    }
}
impl From<bun_alloc::AllocError> for Error<'_> {
    #[cold]
    fn from(error: bun_alloc::AllocError) -> Self {
        Error::pending(error.into())
    }
}

/// An error type a body may return instead of [`Error`]. The thunk converts it.
pub trait IntoError<'a> {
    fn into_error(self, heap: &JsHeap<'a>) -> Error<'a>;
}
impl<'a> IntoError<'a> for Error<'a> {
    #[inline(always)]
    fn into_error(self, _: &JsHeap<'a>) -> Error<'a> {
        self
    }
}
impl<'a> IntoError<'a> for JsError {
    #[inline(always)]
    fn into_error(self, _: &JsHeap<'a>) -> Error<'a> {
        Error::pending(self)
    }
}
impl<'a> IntoError<'a> for bun_sys::Error {
    #[cold]
    fn into_error(self, heap: &JsHeap<'a>) -> Error<'a> {
        Error::unthrown(crate::SysErrorJsc::to_js(&self, heap.global_object()))
    }
}
impl<'a> IntoError<'a> for crate::SystemError {
    #[cold]
    fn into_error(self, heap: &JsHeap<'a>) -> Error<'a> {
        Error::unthrown(self.to_error_instance(heap.global_object()))
    }
}
impl<'a, E: IntoError<'a>> IntoError<'a> for Box<E> {
    #[cold]
    fn into_error(self, heap: &JsHeap<'a>) -> Error<'a> {
        (*self).into_error(heap)
    }
}
impl<'a> IntoError<'a> for core::convert::Infallible {
    fn into_error(self, _: &JsHeap<'a>) -> Error<'a> {
        match self {}
    }
}

// ───────────────────────────── values ─────────────────────────────

/// A [`JSValue`] held by a host call, known to be a `T`. Lists of them go in a [`crate::MarkedArgumentBuffer`].
#[repr(transparent)]
pub struct JsLocal<'a, T = JSValue>(JSValue, InvariantLifetime<'a>, PhantomData<*const T>);
impl<T> Clone for JsLocal<'_, T> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}
impl<T> Copy for JsLocal<'_, T> {}

impl<'a, T> JsLocal<'a, T> {
    #[inline(always)]
    fn from_raw(value: JSValue) -> Self {
        JsLocal(value, PhantomData, PhantomData)
    }

    #[inline(always)]
    fn from_js_result(result: crate::JsResult<JSValue>) -> Result<'a, Self> {
        result.map(Self::from_raw).map_err(Error::pending)
    }

    /// # Safety
    /// `value` is a non-empty `T` that something holds for the call `heap` belongs to.
    #[doc(hidden)]
    #[inline(always)]
    pub unsafe fn from_extern(value: JSValue, _: &JsHeap<'a>) -> Self {
        Self::from_raw(value)
    }

    /// # Safety
    /// As [`Self::from_extern`], or `value` is empty: the caller has no such argument.
    #[doc(hidden)]
    #[inline(always)]
    pub unsafe fn from_extern_or_absent(value: JSValue, _: &JsHeap<'a>) -> Option<Self> {
        (!value.is_empty()).then(|| Self::from_raw(value))
    }

    #[inline(always)]
    pub fn to_js(self) -> JSValue {
        self.0
    }

    #[inline(always)]
    pub fn as_value(self) -> JsLocal<'a> {
        JsLocal::from_raw(self.0)
    }

    /// Keeps the value past the call.
    #[inline]
    pub fn to_strong(self, heap: &JsHeap<'a>) -> Strong {
        Strong::create(self.0, heap.global_object())
    }

    /// The collector sees the value up to here.
    #[doc(hidden)]
    #[inline(always)]
    pub fn keep_alive(self) {
        core::hint::black_box(self.0);
    }
}

/// # Safety
/// `values` are `count` non-empty `T`s that something holds for the call `heap` belongs to.
#[doc(hidden)]
#[inline(always)]
pub unsafe fn rest_from_extern<'a, T>(
    values: *const JSValue,
    count: usize,
    _: &JsHeap<'a>,
) -> &'a [JsLocal<'a, T>] {
    // SAFETY: forwarded; `JsLocal` is `repr(transparent)` over `JSValue`.
    unsafe { core::slice::from_raw_parts(values.cast(), count) }
}

impl<'a> JsLocal<'a> {
    pub const UNDEFINED: Self = JsLocal(JSValue::UNDEFINED, PhantomData, PhantomData);
    pub const NULL: Self = JsLocal(JSValue::NULL, PhantomData, PhantomData);

    /// Where a [`JSValue`] of the older API comes in: one this call was given or made, not one kept from an earlier call.
    #[inline(always)]
    pub fn new(_: &JsHeap<'a>, value: JSValue) -> Self {
        debug_assert!(!value.is_empty());
        Self::from_raw(value)
    }

    #[inline(always)]
    pub fn is_undefined(self) -> bool {
        self.0.is_undefined()
    }

    #[inline]
    pub fn as_callable(self) -> Option<JsLocal<'a, Callable>> {
        self.0.is_callable().then(|| JsLocal::from_raw(self.0))
    }
}

impl<'a> JsLocal<'a> {
    /// A string, not a `String` object.
    #[inline(always)]
    pub fn as_string(self) -> Option<JsLocal<'a, JSString>> {
        self.0
            .is_string_literal()
            .then(|| JsLocal::from_raw(self.0))
    }
}

impl<'a> JsLocal<'a, JSString> {
    /// # Safety
    /// `cell` is a `JSString` that something holds for the call `heap` belongs to.
    #[doc(hidden)]
    #[inline(always)]
    pub unsafe fn from_cell(cell: *mut c_void, _: &JsHeap<'a>) -> Self {
        Self::from_raw(JSValue::from_cell(cell))
    }

    #[inline(always)]
    fn cell(self) -> &'a JSString {
        // SAFETY: a `JsLocal` is never empty, and this one is a `JSString`, whose value is its address.
        unsafe {
            core::hint::assert_unchecked(self.0.encoded() != 0);
            JSString::opaque_ref_nn(self.0.encoded() as *const JSString)
        }
    }

    /// The characters of an 8-bit string that is no rope, where they are: six instructions.
    #[inline(always)]
    pub fn flat_latin1(self) -> Option<JsLatin1<'a>> {
        let owner = self.cell();
        Some(JsLatin1 {
            string: self,
            text: crate::js_string::Latin1Characters {
                owner,
                offset: 0,
                characters: owner.flat_latin1_characters()?,
            },
        })
    }

    /// As [`flat_latin1`](Self::flat_latin1), and of a substring too. `None` for a 16-bit string and for any other rope,
    /// which [`view`](Self::view) serves.
    #[inline]
    pub fn latin1(self) -> Option<JsLatin1<'a>> {
        Some(JsLatin1 {
            string: self,
            text: self.cell().latin1_characters()?,
        })
    }

    /// As [`latin1`](Self::latin1), of a rope too: it is resolved, which fails when there is no memory for it. `None`
    /// for a 16-bit string.
    #[inline]
    pub fn resolved_latin1(self, heap: &JsHeap<'a>) -> Result<'a, Option<JsLatin1<'a>>> {
        if let Some(text) = self.latin1() {
            return Ok(Some(text));
        }
        self.view(heap)?;
        Ok(self.latin1())
    }

    /// The characters of any string. A rope is resolved, which fails when there is no memory for it.
    #[inline]
    pub fn view(self, heap: &JsHeap<'a>) -> Result<'a, crate::JSStringView<'a>> {
        self.cell().view(heap.global_object()).map_err(Error::pending)
    }

    /// How many of the first characters were written to `characters`: all that fit. Nothing is resolved.
    #[inline]
    pub fn first_characters(self, characters: &mut [u16]) -> usize {
        self.cell().first_characters(characters)
    }
}

/// The characters of an 8-bit JS string.
#[derive(Clone, Copy)]
pub struct JsLatin1<'a> {
    string: JsLocal<'a, JSString>,
    text: crate::js_string::Latin1Characters<'a>,
}

impl<'a> JsLatin1<'a> {
    #[inline(always)]
    pub fn characters(&self) -> &'a [u8] {
        self.text.characters
    }

    #[inline(always)]
    pub fn string(&self) -> JsLocal<'a, JSString> {
        self.string
    }

    /// The characters `start..end`, shared with this string and not copied. All of them are this string.
    #[inline(always)]
    pub fn substring(&self, heap: &JsHeap<'a>, start: usize, end: usize) -> JsLocal<'a, JSString> {
        assert!(start <= end && end <= self.text.characters.len());
        // SAFETY: just checked.
        unsafe { self.substring_unchecked(heap, start, end) }
    }

    /// # Safety
    /// `start <= end <= self.characters().len()`.
    #[inline(always)]
    pub unsafe fn substring_unchecked(
        &self,
        heap: &JsHeap<'a>,
        start: usize,
        end: usize,
    ) -> JsLocal<'a, JSString> {
        debug_assert!(start <= end && end <= self.text.characters.len());
        if end - start == self.text.characters.len() {
            return self.string;
        }
        // SAFETY: the owner is no rope, and fewer than the characters that are in it are not all of it.
        JsLocal::from_raw(unsafe {
            self.text.owner.substring_of_resolved(
                heap.global_object(),
                self.text.offset + start as u32,
                (end - start) as u32,
            )
        })
    }

    /// As [`substring_unchecked`](Self::substring_unchecked), several with one call.
    ///
    /// # Safety
    /// `start <= end <= self.characters().len()` of each range.
    #[inline(always)]
    pub unsafe fn substrings_unchecked<const N: usize>(
        &self,
        heap: &JsHeap<'a>,
        ranges: [core::ops::Range<usize>; N],
    ) -> [JsLocal<'a, JSString>; N] {
        let mut offsets_and_lengths = [[0u32; 2]; N];
        let mut index = 0;
        while index < N {
            let range = &ranges[index];
            debug_assert!(range.start <= range.end && range.end <= self.text.characters.len());
            offsets_and_lengths[index] = [
                self.text.offset + range.start as u32,
                (range.end - range.start) as u32,
            ];
            index += 1;
        }
        // SAFETY: the owner is no rope, and the characters are in it.
        let substrings = unsafe {
            self.text
                .owner
                .substrings_of_resolved(heap.global_object(), &offsets_and_lengths)
        };
        // SAFETY: `JsLocal` is `repr(transparent)` over `JSValue`.
        unsafe { (&raw const substrings).cast::<[JsLocal<'a, JSString>; N]>().read() }
    }

    /// `part` as a string: a [`substring`](Self::substring) if it is a slice of [`characters`](Self::characters), a
    /// copy if it lies elsewhere.
    #[inline(always)]
    pub fn part(&self, heap: &JsHeap<'a>, part: &[u8]) -> JsLocal<'a, JSString> {
        let start = (part.as_ptr() as usize).wrapping_sub(self.text.characters.as_ptr() as usize);
        if start <= self.text.characters.len() && part.len() <= self.text.characters.len() - start {
            return self.substring(heap, start, start + part.len());
        }
        heap.create_latin1_string(part)
    }
}

/// Marks a [`JsLocal`] that can be called: a function, or a proxy of one.
pub enum Callable {}

impl<'a> JsLocal<'a, Callable> {
    /// Runs JavaScript.
    pub fn call<T>(
        self,
        cx: &mut JsScope<'a>,
        this: JsLocal<'a, T>,
        args: &[JsLocal<'a>],
    ) -> Result<'a, JsLocal<'a>> {
        // SAFETY: `JsLocal` is `repr(transparent)` over `JSValue`.
        let args = unsafe { &*(core::ptr::from_ref(args) as *const [JSValue]) };
        JsLocal::from_js_result(self.0.call(cx.heap.global_object(), this.0, args))
    }
}

/// Marks a [`JsLocal`] that is a typed array, a `DataView` or an `ArrayBuffer`.
pub enum BufferSource {}

impl<'a> JsLocal<'a, BufferSource> {
    /// The bytes as they are now. A detached or out-of-bounds view is empty.
    #[inline]
    pub fn with_bytes<R>(self, heap: &JsHeap<'a>, f: impl FnOnce(&[u8]) -> R) -> R {
        let array_buffer = self.0.as_array_buffer(heap.global_object());
        let result = f(array_buffer.as_ref().map_or(&[], ArrayBuffer::byte_slice));
        self.0.ensure_still_alive();
        result
    }

    /// As [`with_bytes`](Self::with_bytes), to write them.
    ///
    /// # Safety
    /// Once `f` runs, no other borrow of these bytes is read. Those of another argument can be the same memory.
    #[inline]
    pub unsafe fn with_bytes_mut<R>(self, heap: &JsHeap<'a>, f: impl FnOnce(&mut [u8]) -> R) -> R {
        let mut array_buffer = self.0.as_array_buffer(heap.global_object());
        let result = f(array_buffer
            .as_mut()
            .map_or(&mut [], ArrayBuffer::byte_slice_mut));
        self.0.ensure_still_alive();
        result
    }
}

/// # Safety
/// `wrapped` is the `T` that a cell wraps, and something holds that cell for the call `heap` belongs to.
#[doc(hidden)]
#[inline(always)]
pub unsafe fn class_ref_from_extern<'a, T: crate::JsClass>(
    wrapped: *mut c_void,
    _: &JsHeap<'a>,
) -> &'a T {
    // SAFETY: forwarded.
    unsafe { &*wrapped.cast::<T>() }
}

/// `b.bytes` with `held: "handle"`, for a function that can run JavaScript, which can detach, resize or free a buffer.
#[derive(Clone, Copy)]
pub struct JsBytes<'a> {
    /// What JavaScript does not change: the UTF-8 of a string, or a copy. `None` for a `Blob` or a buffer.
    stable: Option<&'a [u8]>,
    value: JsLocal<'a>,
}

impl<'a> JsBytes<'a> {
    /// # Safety
    /// As [`ExternBytes::get`](extern_types::ExternBytes::get).
    #[doc(hidden)]
    #[inline(always)]
    pub unsafe fn from_extern(
        argument: extern_types::ExternWithValue<extern_types::ExternBytes>,
        heap: &JsHeap<'a>,
    ) -> Self {
        // SAFETY: forwarded.
        unsafe {
            Self {
                stable: argument.converted.get_optional(heap),
                value: JsLocal::from_extern(argument.value, heap),
            }
        }
    }

    /// Those of a buffer are as they are now. A detached or out-of-bounds view is empty.
    #[inline]
    pub fn get<'heap>(self, heap: &'heap JsHeap<'a>) -> &'heap [u8] {
        match self.stable {
            Some(bytes) => bytes,
            // SAFETY: the frame keeps `value` alive, and only JavaScript moves its bytes, which takes the `&mut JsScope` that `'heap` borrows from.
            None => unsafe {
                extern_types::Bun__Bindgen__bytesOfBlobOrBuffer(self.value.0).get(heap)
            },
        }
    }
}

/// `b.bytes` with `string: "asIs"`.
pub enum StringOrJsBytes<'a> {
    /// Latin-1 or UTF-16.
    String(bun_core::String),
    Bytes(JsBytes<'a>),
}

impl<'a> StringOrJsBytes<'a> {
    /// # Safety
    /// As [`ExternBytes::get`](extern_types::ExternBytes::get). The string's ref becomes the result's.
    #[doc(hidden)]
    #[inline]
    pub unsafe fn from_extern(
        argument: extern_types::ExternWithValue<extern_types::ExternString>,
        heap: &JsHeap<'a>,
    ) -> Self {
        if !argument.converted.is_null() {
            return Self::String(extern_types::adopt_string(argument.converted));
        }
        Self::Bytes(JsBytes {
            stable: None,
            // SAFETY: forwarded.
            value: unsafe { JsLocal::from_extern(argument.value, heap) },
        })
    }

    /// `held: "copied"`.
    #[doc(hidden)]
    pub fn into_vec(self, heap: &JsHeap<'a>) -> Vec<u8> {
        let copy = match self {
            Self::String(string) => string.to_owned_slice(),
            Self::Bytes(bytes) => bytes.get(heap).to_vec(),
        };
        heap.global_object().vm().report_extra_memory(copy.len());
        copy
    }
}

/// `b.bytes` with `held: "pinned"`, for a job on another thread to read. It is dropped on the JS thread.
pub struct PinnedBytes(ThreadIsolated<Pinned>);

enum Pinned {
    /// Thread-isolated.
    String(bun_core::Utf8WithString),
    /// GC-rooted too. A resizable one is copied.
    Buffer(PinnedArrayBuffer),
}

// SAFETY: `PinnedBytes::from_extern` builds it so.
unsafe impl ThreadIsolatedArg for Pinned {}

impl PinnedBytes {
    /// # Safety
    /// As [`StringOrJsBytes::from_extern`]. What is not a string is a buffer.
    #[doc(hidden)]
    pub unsafe fn from_extern<'a>(
        argument: extern_types::ExternWithValue<extern_types::ExternString>,
        heap: &JsHeap<'a>,
    ) -> Result<'a, Self> {
        let global = heap.global_object();
        // SAFETY: forwarded.
        let pinned = match unsafe { StringOrJsBytes::from_extern(argument, heap) } {
            StringOrJsBytes::Bytes(bytes) => {
                match PinnedArrayBuffer::root_read_only(global, bytes.value.0) {
                    Some(buffer) => Pinned::Buffer(buffer),
                    None => return Err(global.throw_out_of_memory().into()),
                }
            }
            StringOrJsBytes::String(string) => {
                let utf8 = string.into_utf8_with_string_thread_isolated();
                if !utf8.is_shared() {
                    global.vm().report_extra_memory(utf8.slice().len());
                }
                Pinned::String(utf8)
            }
        };
        // SAFETY: the string is thread-isolated, and the buffer pinned and GC-rooted.
        Ok(Self(unsafe { ThreadIsolated::new(pinned) }))
    }
}

impl core::ops::Deref for PinnedBytes {
    type Target = [u8];
    #[inline]
    fn deref(&self) -> &[u8] {
        match &*self.0 {
            Pinned::String(utf8) => utf8.slice(),
            Pinned::Buffer(buffer) => buffer.slice(),
        }
    }
}

// ───────────────────────────── classes ─────────────────────────────

/// The Rust struct of a generated class, stored inside its JS wrapper and dropped by the sweeper.
///
/// # Safety
/// Implemented by generated code only: the offsets describe the generated C++ cell.
pub unsafe trait JsPayload: Sized + 'static {
    #[doc(hidden)]
    const PAYLOAD_OFFSET: usize;
    #[doc(hidden)]
    const INTERNAL_FIELDS_OFFSET: usize;
    /// # Safety
    /// The caller writes the payload before anything else runs. A null `structure` is the class's own.
    #[doc(hidden)]
    unsafe fn create_cell(global: *mut JSGlobalObject, structure: *mut c_void) -> NonNull<c_void>;

    /// A new JS object that owns `self`.
    #[inline]
    fn into_js<'a>(self, heap: &JsHeap<'a>) -> JsWrapper<'a, Self> {
        // SAFETY: a null structure is always valid.
        unsafe { JsWrapper::create_with_structure(heap, core::ptr::null_mut(), self) }
    }
}

/// The JS object that wraps a `T`. The payload is reached only through [`JsPayloads`].
#[repr(transparent)]
pub struct JsWrapper<'a, T: JsPayload>(
    NonNull<c_void>,
    InvariantLifetime<'a>,
    PhantomData<*const T>,
);
impl<T: JsPayload> Clone for JsWrapper<'_, T> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}
impl<T: JsPayload> Copy for JsWrapper<'_, T> {}

impl<'a, T: JsPayload> JsWrapper<'a, T> {
    /// # Safety
    /// `cell` is a wrapper of `T` that something holds for the call `heap` belongs to.
    #[doc(hidden)]
    #[inline(always)]
    pub unsafe fn from_extern(cell: NonNull<c_void>, _: &JsHeap<'a>) -> Self {
        JsWrapper(cell, PhantomData, PhantomData)
    }

    /// # Safety
    /// `structure` is null or a Structure of `T`'s cell class.
    #[doc(hidden)]
    #[inline]
    pub unsafe fn create_with_structure(
        heap: &JsHeap<'a>,
        structure: *mut c_void,
        payload: T,
    ) -> Self {
        // SAFETY: nothing runs between the allocation and the write, which cannot panic.
        unsafe {
            let this = Self::from_extern(T::create_cell(heap.global_ptr(), structure), heap);
            this.payload().write(payload);
            this
        }
    }

    /// # Safety
    /// Nothing can reach the payload mutably for `'b`, and the caller's frame holds the cell.
    #[doc(hidden)]
    #[inline(always)]
    pub unsafe fn payload_ref<'b>(self) -> &'b T {
        // SAFETY: forwarded.
        unsafe { &*self.payload() }
    }

    /// # Safety
    /// Nothing else can reach the payload for `'b`, and the caller's frame holds the cell.
    #[doc(hidden)]
    #[inline(always)]
    pub unsafe fn payload_mut<'b>(self) -> &'b mut T {
        // SAFETY: forwarded.
        unsafe { &mut *self.payload() }
    }

    #[inline(always)]
    fn payload(self) -> *mut T {
        // SAFETY: generated offset inside the cell.
        unsafe { self.0.as_ptr().byte_add(T::PAYLOAD_OFFSET).cast() }
    }

    #[inline(always)]
    pub fn as_value(self) -> JsLocal<'a, JSObject> {
        JsLocal::from_raw(JSValue::from_cell(self.0.as_ptr()))
    }

    /// Lends the payload. `f` cannot run JavaScript: that takes the `&mut JsScope` the `JsPayloads` is borrowed from.
    #[inline(always)]
    pub fn with<R>(self, _: &JsPayloads<'a>, f: impl FnOnce(&T) -> R) -> R {
        // SAFETY: a `&mut T` is lent by `with_mut`, which holds `JsPayloads` exclusively, or to a body that has no `JsPayloads`.
        let result = f(unsafe { &*self.payload() });
        self.as_value().0.ensure_still_alive();
        result
    }

    /// As [`with`](Self::with), exclusively.
    #[inline(always)]
    pub fn with_mut<R>(self, _: &mut JsPayloads<'a>, f: impl FnOnce(&mut T) -> R) -> R {
        // SAFETY: the exclusive borrow of `JsPayloads` excludes every other payload reference.
        let result = f(unsafe { &mut *self.payload() });
        self.as_value().0.ensure_still_alive();
        result
    }

    /// Keeps the wrapper, and so the payload, alive past the call.
    #[inline]
    pub fn to_strong(self, heap: &JsHeap<'a>) -> JsWrapperStrong<T> {
        JsWrapperStrong(self.as_value().to_strong(heap), PhantomData)
    }

    /// # Safety
    /// `index` is one of the class's `internalFields`.
    #[doc(hidden)]
    #[inline(always)]
    pub unsafe fn internal_field(self, _: &JsHeap<'a>, index: usize) -> JsLocal<'a> {
        // SAFETY: generated offset inside the cell; they are initialized to `undefined`.
        JsLocal::from_raw(unsafe {
            self.0
                .as_ptr()
                .byte_add(T::INTERNAL_FIELDS_OFFSET)
                .cast::<JSValue>()
                .add(index)
                .read()
        })
    }

    /// # Safety
    /// As [`internal_field`](Self::internal_field).
    #[doc(hidden)]
    #[inline(always)]
    pub unsafe fn set_internal_field<V>(
        self,
        heap: &JsHeap<'a>,
        index: usize,
        value: JsLocal<'a, V>,
    ) {
        // SAFETY: as above; C++ stores through the `WriteBarrier`.
        unsafe {
            extern_types::Bun__Bindgen__setInternalField(
                heap.global_ptr(),
                self.0.as_ptr(),
                (T::INTERNAL_FIELDS_OFFSET + index * size_of::<JSValue>()) as u32,
                value.0,
            )
        }
    }
}

/// A [`Strong`] on a wrapper; gives it back to code that has a capability again.
pub struct JsWrapperStrong<T: JsPayload>(Strong, PhantomData<*const T>);
impl<T: JsPayload> JsWrapperStrong<T> {
    #[inline]
    pub fn get<'a>(&self, heap: &JsHeap<'a>) -> JsWrapper<'a, T> {
        // SAFETY: made from a `JsWrapper<T>`; a cell value is its pointer.
        unsafe {
            JsWrapper::from_extern(
                NonNull::new_unchecked(self.0.get().encoded() as *mut c_void),
                heap,
            )
        }
    }
}

// ───────────────────────────── results ─────────────────────────────

/// Rust to JS, one function per schema type, because the Rust type does not say which: a `Vec<u8>` is a string or an array of numbers.
pub mod to_js {
    use super::*;

    macro_rules! number {
        ($($name:ident: $t:ty => $f:expr;)*) => {$(
            #[inline(always)]
            pub fn $name<'a>(_: &JsHeap<'a>, value: $t) -> Result<'a, JsLocal<'a>> {
                Ok(JsLocal::from_raw($f(value)))
            }
        )*};
    }
    number! {
        bool: bool => JSValue::from;
        u8: u8 => |n| JSValue::js_number_from_int32(i32::from(n));
        u16: u16 => |n| JSValue::js_number_from_int32(i32::from(n));
        i32: i32 => JSValue::js_number_from_int32;
        u32: u32 => |n| JSValue::js_number_from_uint64(u64::from(n));
        u64: u64 => JSValue::js_number_from_uint64;
        usize: usize => |n| JSValue::js_number_from_uint64(n as u64);
        f64: f64 => |n| JSValue::js_number(JSValue::purify_nan(n));
    }

    #[inline]
    pub fn u64_as_bigint<'a>(heap: &JsHeap<'a>, value: u64) -> Result<'a, JsLocal<'a>> {
        JsLocal::from_js_result(JSValue::from_uint64_no_truncate(
            heap.global_object(),
            value,
        ))
    }

    #[inline(always)]
    pub fn undefined<'a>(_: &JsHeap<'a>, (): ()) -> Result<'a, JsLocal<'a>> {
        Ok(JsLocal::UNDEFINED)
    }

    /// A body may also return a plain [`JSValue`]: it goes straight back to JSC.
    pub trait Any<'a> {
        fn into_value(self, heap: &JsHeap<'a>) -> JsLocal<'a>;
    }
    impl<'a, T> Any<'a> for JsLocal<'a, T> {
        #[inline(always)]
        fn into_value(self, _: &JsHeap<'a>) -> JsLocal<'a> {
            self.as_value()
        }
    }
    impl<'a> Any<'a> for JSValue {
        #[inline(always)]
        fn into_value(self, heap: &JsHeap<'a>) -> JsLocal<'a> {
            JsLocal::new(heap, self)
        }
    }

    #[inline(always)]
    pub fn any<'a>(heap: &JsHeap<'a>, value: impl Any<'a>) -> Result<'a, JsLocal<'a>> {
        Ok(value.into_value(heap))
    }

    #[inline(always)]
    pub fn local_string<'a>(
        _: &JsHeap<'a>,
        value: JsLocal<'a, JSString>,
    ) -> Result<'a, JsLocal<'a>> {
        Ok(value.as_value())
    }

    /// A body whose bytes do not outlive it returns the string, from [`JsHeap::create_utf8_string`].
    pub trait Utf8<'a> {
        fn into_string(self, heap: &JsHeap<'a>) -> Result<'a, JsLocal<'a, JSString>>;
    }
    impl<'a, T: AsRef<[u8]>> Utf8<'a> for T {
        #[inline]
        fn into_string(self, heap: &JsHeap<'a>) -> Result<'a, JsLocal<'a, JSString>> {
            heap.create_utf8_string(self.as_ref())
        }
    }
    impl<'a> Utf8<'a> for JsLocal<'a, JSString> {
        #[inline(always)]
        fn into_string(self, _: &JsHeap<'a>) -> Result<'a, JsLocal<'a, JSString>> {
            Ok(self)
        }
    }

    #[inline(always)]
    pub fn utf8<'a>(heap: &JsHeap<'a>, value: impl Utf8<'a>) -> Result<'a, JsLocal<'a>> {
        value.into_string(heap).map(JsLocal::as_value)
    }

    #[inline]
    pub fn string<'a>(heap: &JsHeap<'a>, value: bun_core::String) -> Result<'a, JsLocal<'a>> {
        JsLocal::from_js_result(crate::StringJsc::into_js(value, heap.global_object()))
    }

    #[inline]
    pub fn array<'a, I: IntoIterator>(
        heap: &JsHeap<'a>,
        items: I,
        mut convert: impl FnMut(&JsHeap<'a>, I::Item) -> Result<'a, JsLocal<'a>>,
    ) -> Result<'a, JsLocal<'a>> {
        let global = heap.global_object();
        // A short array is made with one call. A longer one takes a call per element.
        let mut short = [JSValue::ZERO; 8];
        let mut items = items.into_iter();
        for count in 0..short.len() {
            let Some(item) = items.next() else {
                // SAFETY: `count` initialized values.
                return JsLocal::from_js_result(crate::call_zero_is_throw(global, || unsafe {
                    extern_types::Bun__Bindgen__constructArrayFromValues(
                        heap.global_ptr(),
                        short.as_ptr(),
                        count,
                    )
                }));
            };
            short[count] = convert(heap, item)?.0;
        }
        let array = JSValue::create_empty_array(global, short.len() + items.size_hint().0)?;
        let rest = items.map(|item| convert(heap, item).map(|value| value.0));
        for (index, value) in short.into_iter().map(Ok).chain(rest).enumerate() {
            array.put_index(global, index as u32, value?)?;
        }
        Ok(JsLocal::from_raw(array))
    }

    /// An empty value is a member that is absent.
    ///
    /// # Safety
    /// `Tables::memberNames` names `values`, from `first_member_name_index`. They are the members of the returned
    /// dictionary number `dictionary_index`, of which `has_every_member` says that none is absent.
    #[doc(hidden)]
    #[inline]
    pub unsafe fn object<'a>(
        heap: &JsHeap<'a>,
        first_member_name_index: u32,
        dictionary_index: u32,
        has_every_member: bool,
        values: &[JSValue],
    ) -> Result<'a, JsLocal<'a>> {
        // SAFETY: forwarded; this cannot throw.
        Ok(JsLocal::from_raw(unsafe {
            extern_types::Bun__Bindgen__createObject(
                heap.global_ptr(),
                first_member_name_index,
                dictionary_index,
                has_every_member,
                values.as_ptr(),
                values.len(),
            )
        }))
    }

    /// # Safety
    /// `index` is one into `Tables::enumerationValues`.
    #[doc(hidden)]
    #[inline]
    pub unsafe fn enumeration_value<'a>(heap: &JsHeap<'a>, index: u32) -> Result<'a, JsLocal<'a>> {
        // SAFETY: forwarded; this cannot throw.
        Ok(JsLocal::from_raw(unsafe {
            extern_types::Bun__Bindgen__enumerationValueToJS(heap.global_ptr(), index)
        }))
    }
}

#[doc(hidden)]
#[inline(always)]
pub fn host_fn_return<'a, T, E: IntoError<'a>>(
    cx: &mut JsScope<'a>,
    result: core::result::Result<T, E>,
    convert: impl FnOnce(&JsHeap<'a>, T) -> Result<'a, JsLocal<'a>>,
) -> JSValue {
    let value = 'value: {
        let error = match result {
            Ok(value) => match convert(&cx.heap, value) {
                Ok(value) => break 'value value.0,
                Err(error) => error,
            },
            Err(error) => error.into_error(&cx.heap),
        };
        error.into_host_fn_return(cx)
    };
    debug_assert_eq!(
        value.is_empty(),
        cx.heap.global_object().has_exception(),
        "a body fails exactly when an exception is pending",
    );
    value
}
